def service(handler):
    server=http.server.ThreadingHTTPServer(('127.0.0.1',0),handler);server.daemon_threads=False
    t=threading.Thread(target=server.serve_forever,kwargs={'poll_interval':.01});t.start()
    try:yield server.server_port
    finally:server.shutdown();server.server_close();t.join(1);assert not t.is_alive()
class Quiet(http.server.BaseHTTPRequestHandler):
    def log_message(self,*args):pass
    def answer(self,status,body=b'',headers=None):
        self.send_response(status)
        for k,v in (headers or []):self.send_header(k,v)
        self.send_header('Content-Length',str(len(body)));self.end_headers()
        try:self.wfile.write(body)
        except OSError:pass


peers=[];arrivals=[];release=threading.Event();lock=threading.Lock()
class Reuse(Quiet):
    protocol_version='HTTP/1.1'
    def do_GET(self):
        with lock:peers.append(self.client_address)
        if self.path.startswith('/hold'):
            with lock:arrivals.append(self.path)
            if not release.wait(2):self.answer(504,b'gate timeout');return
        self.answer(200,b'actual upstream')
with service(Reuse) as a:
    with nginx({'UPSTREAM':a}) as p:
        for _ in range(3):assert request(p,'/',headers={'Connection':'close'})[0]==200
        assert len(set(peers))==1,'upstream connection not reused'
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fs=[pool.submit(request,p,f'/hold/{i}') for i in range(3)]
            try:
                until=time.monotonic()+1.5
                while len(arrivals)<3 and time.monotonic()<until:time.sleep(.01)
                assert len(arrivals)==3,'keepalive confused with active connection cap'
            finally:release.set()
            assert all(f.result()[0]==200 for f in fs)

